/**
 * 枚举描述结构放置的旋转方式。
 */
export enum StructureRotation {
    /**
     * @remarks
     * 无旋转。
     *
     */
    None = 'None',
    /**
     * @remarks
     * 旋转180度。
     *
     */
    Rotate180 = 'Rotate180',
    /**
     * @remarks
     * 旋转270度。
     *
     */
    Rotate270 = 'Rotate270',
    /**
     * @remarks
     * 旋转90度。
     *
     */
    Rotate90 = 'Rotate90',
}